#[cfg(test)]
mod new_order_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_new_order_codec() {
        let original = NewOrder {
            submitting_pbuid: "a".repeat(6),
            security_id: "a".repeat(8),
            security_id_source: "a".repeat(4),
            owner_type: 1234,
            clearing_firm: "a".repeat(2),
            transact_time: -123456789,
            user_info: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            account_id: "a".repeat(12),
            branch_id: "a".repeat(4),
            order_restrictions: "a".repeat(4),
            side: "a".to_string(),
            ord_type: "a".to_string(),
            order_qty: -123456789,
            price: -123456789,
            appl_id: "010".to_string(),
            appl_extend: NewOrderApplExtendEnum::Extend100101(Extend100101 {
                stop_px: -123456789,
                min_qty: -123456789,
                max_price_levels: 1234,
                time_in_force: "a".to_string(),
                cash_margin: "a".to_string(),
            }),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(NewOrderRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        NewOrder::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = NewOrder::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

